'use strict';
const data=JSON.parse(document.getElementById('report-data').textContent);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const duration=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
const num=n=>Number(n??0).toLocaleString('en-US');
const hero=id=>data.assets.heroes[String(id)]||{};
const heroName=id=>hero(id).zh_name||hero(id).name_zh||hero(id).name_en||`英雄 ${id}`;
const heroImage=id=>hero(id).portrait||hero(id).image||hero(id).icon;
const portrait=(id,cls='')=>heroImage(id)?`<img class="${esc(cls)}" src="${esc(heroImage(id))}" alt="${esc(heroName(id))}" loading="eager">`:`<span>${esc(heroName(id))}</span>`;
const item=id=>data.assets.items[String(id)]||{};
function itemIcon(id,index){if(!id)return index<6?'<span class="empty"></span>':'';const v=item(id);return v.icon||v.image?`<img class="item ${index>5?'extra':''}" src="${esc(v.icon||v.image)}" alt="${esc(v.zh_name||v.name_zh||v.internal_name||id)}" title="${esc(v.zh_name||v.name_zh||v.internal_name||id)}">`:`<span class="chip">${esc(id)}</span>`;}
const flatten=v=>typeof v==='string'?v:(v?.body||v?.comment||v?.text||v?.reason||'');
const foot=(tag,page)=>`<div class="footer"><span>新和联胜·刀塔堡垒</span><span>${esc(tag)} / ${esc(page)}</span></div>`;
const head=(m,category,index)=>`<div class="kicker"><span>CLUB ARCHIVE · MATCH ${String(m.number).padStart(2,'0')}</span><span>${esc(category)}</span></div><div class="brand">新和联胜·刀塔堡垒</div><div class="eyebrow" style="margin-top:8px">${esc(m.start_local)} · ${duration(m.duration)} · #${m.match_id}</div>`;
const section=(id,body)=>`<section class="capture-page" id="${id}" data-capture="${id}">${body}</section>`;
const title=(text,small='')=>`<div class="section-title"><h3>${esc(text)}</h3><small>${esc(small)}</small></div>`;
const nameOf=(m,slot)=>m.players.find(p=>p.player_slot===Number(slot))?.name||'';
function lineup(m,isRadiant){return `<div class="lineup-title ${isRadiant?'r':'d'}">${isRadiant?'天辉 / RADIANT':'夜魇 / DIRE'} ${m.radiant_win===isRadiant?'· 胜':''}</div><div class="lineup">${m.players.filter(p=>p.is_radiant===isRadiant).map(p=>`<div>${portrait(p.hero_id)}<div class="hero">${esc(heroName(p.hero_id))}</div><div class="name">${esc(p.name)}</div></div>`).join('')}</div>`;}
function matchStory(m){const e=m.editorial,chosen=m.players.find(p=>p.player_slot===e.mvp.selected_slot);const reason=e.mvp.candidates.find(c=>c.player_slot===e.mvp.selected_slot)?.reason||e.mvp.reason||'';return section(`match-${m.match_id}-01`,`${head(m,'赛果 · 转折',1)}<h1>${esc(e.title)}</h1><p class="lead">${esc(e.lead)}</p><div class="scoreboard"><div class="side r"><span>天辉</span><strong>${m.radiant_score}</strong><em>${m.radiant_win?'VICTORY':''}</em></div><div class="versus">VS<br>${duration(m.duration)}</div><div class="side d"><span>夜魇</span><strong>${m.dire_score}</strong><em>${!m.radiant_win?'VICTORY':''}</em></div></div>${lineup(m,true)}${lineup(m,false)}<div class="mvp"><div class="mvp-top">${portrait(chosen.hero_id)}<div><span class="badge">俱乐部评选 MVP</span><div class="winner-name">${esc(chosen.name)}</div><div class="hero-title">${esc(heroName(chosen.hero_id))} · ${chosen.kills}/${chosen.deaths}/${chosen.assists}</div></div></div><p class="reason">${esc(reason)}</p><div class="candidates">候选：${e.mvp.candidates.filter(c=>c.player_slot!==chosen.player_slot).map(c=>esc(nameOf(m,c.player_slot))).join(' / ')} · 综合关键事件与终局贡献</div></div>${title('比赛的转折点','事件时间线')}<div>${e.key_moments.map(t=>`<div class="moment"><span class="time">${esc(t.time)}</span><h4>${esc(t.title)}</h4><p>${esc(t.event)}</p><p class="comment">${esc(t.comment)}</p></div>`).join('')}</div><div class="verdict">${esc(e.closing)}</div>${foot(`第${m.number}局`, '01 · 赛果')}`);}
function draftPage(m){const e=m.editorial;return section(`match-${m.match_id}-02`,`${head(m,'BP · 装备',2)}<h1>三轮博弈<br><span class="gold">把阵容拼出来</span></h1><p class="lead">队长模式 · 双方固定分栏 · 按回放还原全部选禁</p>${m.draft_html}<div class="divider"></div>${title('关键装备与复活币','购入记录 / 买活事件')}${e.item_comments.map(t=>`<div class="equipment-note">${typeof t==='string'?esc(t):`<span class="badge">${esc(t.time||'')}</span> <strong>${esc(nameOf(m,t.player_slot)||t.player_name||'')}</strong> ${esc(t.item_name||'')}<br>${esc(t.comment||t.body||'')}`}</div>`).join('')}<p class="prose">${esc(e.buyback_comment)}</p><p class="quality">#号是全局选禁顺序；本方第N选表示选择先后，不代表一至五号位。逐手操作时间和BP操作者未记录。</p>${foot(`第${m.number}局`, '02 · BP')}`);}
function playerCard(m,p){const e=m.editorial,comment=e.players.find(v=>v.player_slot===p.player_slot)?.comment||'';const stat=(label,v)=>`<div class="stat"><span>${label}</span><b>${num(v)}</b></div>`;return `<article class="player-card ${p.is_radiant?'':'dire'}"><div class="player-head">${portrait(p.hero_id)}<div class="identity"><div class="name">${esc(p.name)}${e.mvp.selected_slot===p.player_slot?'<span class="player-mvp">MVP</span>':''}</div><div class="hero">${esc(heroName(p.hero_id))} · Lv.${p.level}</div></div><div class="kda">${p.kills}/${p.deaths}/${p.assists}<small>K / D / A</small></div></div><div class="stats">${stat('GPM',p.gold_per_min)}${stat('XPM',p.xp_per_min)}${stat('补刀',p.last_hits)}${stat('净值',p.net_worth)}${stat('英雄伤害',p.hero_damage)}${stat('建筑伤害',p.tower_damage)}${stat('治疗',p.hero_healing)}${stat('反补',p.denies)}</div><div class="items">${p.items.map((v,i)=>itemIcon(v,i)).join('')}</div><p class="player-comment">${esc(comment)}</p></article>`;}
function teamPage(m,isRadiant){const n=isRadiant?3:4,won=m.radiant_win===isRadiant;return section(`match-${m.match_id}-0${n}`,`${head(m,'十人终局 · 锐评',n)}<h1><span class="${isRadiant?'r':'d'}">${isRadiant?'天辉':'夜魇'}五人</span><br>${won?'胜利怎么打出来':'败局也要看清楚'}</h1><p class="lead">${won?'获胜':'失利'} · 终局成绩与装备 · 每人一条有据锐评</p>${m.players.filter(p=>p.is_radiant===isRadiant).map(p=>playerCard(m,p)).join('')}<p class="quality">终局数据来自回放赛后摘要；金边物品为额外槽位。锐评围绕本场表现。经济曲线、站位与技能命中未可靠还原。</p>${foot(`第${m.number}局`, `0${n} · ${isRadiant?'天辉':'夜魇'}`)}`);}
function weeklyStats(){const map=new Map;for(const m of data.matches)for(const p of m.players){let q=map.get(p.player_key)||{name:p.name,games:0,wins:0,kills:0,deaths:0,assists:0};q.name=p.name;q.games++;q.wins+=p.win?1:0;q.kills+=p.kills;q.deaths+=p.deaths;q.assists+=p.assists;map.set(p.player_key,q);}return [...map.values()].sort((a,b)=>b.games-a.games||b.wins-a.wins);}
function overview(){const o=data.overview;const getTitle=t=>typeof t==='string'?'本周观察':t.title;return section('week-01',`<div class="kicker"><span>CLUB ARCHIVE / WEEKLY</span><span>2026 · VOL.01</span></div><div class="brand">新和联胜·刀塔堡垒</div><h1>五场对黑<br><span class="gold">谁在杀人，谁在拆家</span></h1><p class="lead">10 月 9 日晚三场 · 10 月 11 日下午两场<br>${esc(o.intro||'回放核验后的俱乐部战报')}</p><div class="week-stat"><div><b>05</b><span>自建房间对局</span></div><div><b>${data.unique_players}</b><span>不同参赛账号</span></div><div><b>${data.appearance_count}</b><span>出场记录</span></div></div>${data.matches.map(m=>{const p=m.players.find(v=>v.player_slot===m.editorial.mvp.selected_slot);return `<div class="week-match"><div class="top"><span>第 ${m.number} 局 · ${m.start_local}</span><span>${duration(m.duration)}</span></div><div style="display:flex;align-items:center;gap:10px;margin-top:5px"><div class="score"><span class="r">${m.radiant_score}</span><span style="color:#657282;font-size:15px"> : </span><span class="d">${m.dire_score}</span></div><span class="badge">${m.radiant_win?'天辉':'夜魇'}胜</span></div><div class="match-name">${esc(m.editorial.title)}</div><div class="mini">MVP · ${esc(p.name)} / ${esc(heroName(p.hero_id))}</div><a href="?match=${m.match_id}">打开本局完整复盘 →</a></div>`}).join('')}${title('本周看点','小样本，真记录')}${o.highlights.map(h=>`<div class="highlight"><h3>${esc(getTitle(h))}</h3><p>${esc(flatten(h))}</p></div>`).join('')}<p class="quality">俱乐部 MVP 由本次复盘评选；参赛账号数量不自动等于微信群成员数量。${esc(data.quality_note)}</p>${foot('2026.10.05 — 10.11', '01 · 周总览')}`)+section('week-02',`<div class="kicker"><span>CLUB ARCHIVE / PLAYERS</span><span>16 PLAYERS</span></div><div class="brand">新和联胜·刀塔堡垒</div><h1>十六人<br><span class="gold">逐个点名</span></h1><p class="lead">按账号去重 · AMS 与首局“不怪她”为同一人<br>胜率与组合均只覆盖这五场。</p><div class="members-grid">${weeklyStats().map(p=>{const c=o.players.find(v=>v.name===p.name||p.name==='AMS'&&v.name.includes('AMS'));return `<div class="member"><div class="member-name">${esc(p.name)}</div><div class="member-record">${p.games} 场 ${p.wins} 胜 · ${p.kills}/${p.deaths}/${p.assists}</div><p>${esc(c?.comment||'逐场表现见对局数据页。')}</p></div>`}).join('')}</div>${title('搭子观察','同队记录，并非纯双排')}${o.pairs.map(p=>`<p class="pair"><span class="gold">${esc(Array.isArray(p.names)?p.names.join(' + '):p.names||p.name||'')}</span><br>${p.games??p.matches??''} 场 ${p.wins??''} 胜 · ${esc(flatten(p))}</p>`).join('')}${foot('2026.10.05 — 10.11', '02 · 点名')}`);}
function render(matchId){const m=data.matches.find(m=>String(m.match_id)===String(matchId));document.getElementById('app').innerHTML=m?matchStory(m)+draftPage(m)+teamPage(m,true)+teamPage(m,false):overview();document.getElementById('navigation').innerHTML=[{id:'',label:'总览'},...data.matches.map(m=>({id:m.match_id,label:`第${m.number}局`}))].map(t=>`<button class="${String(t.id)===String(m?.match_id||'')?'active':''}" data-match="${t.id}">${t.label}</button>`).join('');document.querySelectorAll('[data-match]').forEach(b=>b.addEventListener('click',()=>{const q=new URLSearchParams(location.search);q.set('match',b.dataset.match||'overview');history.replaceState(null,'',location.pathname+(q.size?'?'+q:''));render(b.dataset.match);scrollTo(0,0)}));document.title=m?`第${m.number}局 · ${m.editorial.title}`:'新和联胜 · 五局对黑实录';window.reportReady=true;}
const query=new URLSearchParams(location.search);if(query.has('capture'))document.documentElement.classList.add('capture-mode');render(query.has('match')?query.get('match'):document.body.dataset.match);
